    "description": "A hemispherical silver tea infuser with an ebony handle and a cross-shaped strainer. The body is hand-raised from a single sheet of silver; the handle is turned ebony on a brass mount. The hemisphere sits in a saucer-like tray that catches drips. Every surface is polished to a mirror finish. Brandt was twenty-one when she made it in the Bauhaus metal workshop under László Moholy-Nagy.",
    "significance": "The MT49 is the Bauhaus manifesto in miniature: geometric form, truth to material, workshop made. But it's also a correction — Brandt proved that the metal workshop, dominated by men, could produce its most refined objects through a woman's hands. The tea infuser is impossibly precise for a student piece. It set the standard that made the Bauhaus metalwork programme famous.",
