    "movement": "Fibre Art",
    "wikiTitle": null,
    "description": "Small woven rectangles — typically 10–25cm — made from linen, silk, wool, cotton, and found threads, each one an intense colour study and structural experiment. Hicks has made thousands since 1960, treating them as a continuous research practice. They function as sketches, propositions, gifts, and autonomous works simultaneously. No two are identical. They are the unit of her thinking.",
    "significance": "The Minimes collapse the distinction between sketch and finished work, between craft and art, between small and significant. Each one takes the same time and attention as a monumental installation, just compressed. They prove that scale is not a measure of ambition — and that a lifelong daily practice of making small things is itself a major body of work.",
