    "collection": "Studebaker National Museum, South Bend",
    "movement": "American Industrial Design",
    "wikiTitle": "Studebaker_Starliner",
    "description": "A two-door hardtop coupé with a dramatically low roofline, wraparound rear window, and minimal chrome trim — designed by Loewy's team including Robert Bourke. The Starliner reversed the Detroit formula: where GM and Ford piled on chrome, fins, and bulk, Loewy stripped the car down to clean European-influenced proportions. It was the most advanced-looking American car of 1953 and the worst-selling — too ahead of its market.",
    "significance": "Loewy's MAYA principle — Most Advanced Yet Acceptable — was deliberately violated by his own team. The Starliner was too advanced and not acceptable enough. It proves that the designer's most famous theory has limits: being right about form doesn't guarantee being right about timing. The car Detroit wasn't ready for became the one collectors prize most.",
    "connections": [
      {
        "id": 184,
        "type": "sameProblem",
        "reason": "The Routemaster Bus (1956) and the Starliner (1953) are both vehicles designed against their industry's conventions — the Routemaster built to last in an era of planned obsolescence, the Starliner stripped of chrome in an era of chrome excess. Both commercial failures. Both design classics."
      },
      {
        "id": 77,
        "type": "zeitgeist",
        "reason": "Propst's Action Office II (1968) and Loewy's Starliner (1953) are both American designs that their markets rejected — the office system became the cubicle, the car became a commercial failure. Both proved too radical for the industries they tried to reform. Design that's right but early."
      },
      {
        "id": 98,
        "type": "argument",
        "reason": "Braun's Pocket de Luxe reduces the electric shaver to anonymous geometric efficiency — the machine disappears. Loewy's Starliner reduces the American car to European proportion and clean line — the chrome disappears. German and American minimalism arriving at the same conclusion: less is more sellable (eventually)."
      }
    ],
