    "movement": "Japanese Minimalism",
    "wikiTitle": null,
    "description": "A campaign poster showing a Bolivian salt flat stretching to the horizon — sky above, white ground below, nothing else. No product, no logo in the image, no text beyond the MUJI logotype at the bottom edge. The horizon line divides the poster precisely. Hara's concept: emptiness as the ultimate brand expression. The less MUJI shows, the more MUJI it becomes.",
    "significance": "Hara reversed the logic of advertising: instead of filling space with messages, he emptied it. The Horizon campaign argues that a brand's identity is not what it says but what it refuses to say. MUJI — 'no-brand quality goods' — needed a visual language of absence. Hara found it in the most absent landscape on earth.",
    "connections": [
      {
        "id": 55,
        "type": "argument",
        "reason": "Vignelli's New York Subway Signage (1970) builds brand identity through systematic presence — every station, every sign, one typeface. Hara's MUJI Horizon (2003) builds brand identity through systematic absence — no product, no message, one empty landscape. Maximum information versus maximum emptiness, both achieving total brand recognition."
      },
      {
        "id": 14,
        "type": "method",
        "reason": "Tschichold's Penguin rules create identity through strict typographic constraints — what you cannot do defines the brand. Hara's Horizon creates identity through strict visual emptiness — what you refuse to show defines the brand. Both systems where restriction generates recognition."
      },
      {
        "id": 163,
        "type": "argument",
        "reason": "Memphis's Swatch collaboration (1986) puts maximum pattern on minimum surface — the watch as graphic explosion. Hara's MUJI Horizon (2003) puts minimum content on maximum surface — the poster as graphic implosion. Two extremes of how design communicates value."
      }
    ],
