    "movement": "Phenomenological Architecture",
    "wikiTitle": "Therme_Vals",
    "description": "A thermal bath built into the mountainside at Vals, Graubünden, using locally quarried Valser quartzite. Sixty thousand stone slabs stacked in layers create walls, floors, and ceilings that appear to have been carved from the mountain rather than built. Light enters through precisely cut slots between roof slabs. Steam, water, stone, darkness, and controlled views compose a spatial sequence that is closer to geological formation than architectural composition.",
    "significance": "Zumthor demonstrates that architecture's primary materials are not steel and glass but light, temperature, sound, and touch. Therme Vals is designed for the body rather than the eye — you feel the building before you understand it. It's the definitive argument that architecture is a sensory discipline, not a visual one.",
    "connections": [
      {
        "id": 59,
        "type": "argument",
        "reason": "Mies's Farnsworth House (1951) dissolves the wall into glass — the building disappears so that nature can enter visually. Zumthor's Therme Vals (1996) thickens the wall into mountain stone — the building absorbs so that nature can enter physically. Glass versus quartzite, transparency versus immersion."
      },
      {
        "id": 836,
        "type": "method",
        "reason": "Zumthor's Therme Vals (1996) creates an architecture experienced through the body — temperature, steam, stone under bare feet. The Raku tea bowl (c.1580) creates a ceramic experienced through the body — warmth, weight, roughness in cupped hands. Both are objects whose meaning is inaccessible through photographs — you must touch them to understand them."
      },
      {
        "id": 35,
        "type": "sameProblem",
        "reason": "Utzon's Sydney Opera House (1973) and Zumthor's Therme Vals (1996) both respond to their sites with forms that seem to grow from them — shells rising from a harbour, stone descending into a mountain. Both insist that a building's first obligation is to its landscape."
      }
    ],
