    "collection": "MIT Museum, Cambridge MA",
    "movement": "Computational Design / Material Ecology",
    "wikiTitle": null,
    "description": "A dome-shaped pavilion whose primary structure is a CNC-wound silk thread scaffold over which 6,500 live silkworms were released. The worms filled gaps in the scaffold with their own silk, responding to light gradients: denser silk in darker areas, sparser silk where light was brighter. The pavilion is co-designed by algorithm, robot, and living organism. The silkworms die naturally after completing their work.",
    "significance": "The Silk Pavilion dissolves the boundary between design, fabrication, and biology. The designer sets initial conditions — the scaffold geometry, the light gradients — and then surrenders control to organisms whose behaviour is the manufacturing process. It's the most radical proposition in contemporary design: that the maker might not be human, and that design might be a negotiation between species.",
    "connections": [
      {
        "id": 626,
        "type": "argument",
        "reason": "Formafantasma's Ore Streams (2017) traces the geological and political life of materials already extracted — design as forensic analysis of the past. Oxman's Silk Pavilion (2013) deploys living organisms to generate materials in real time — design as biological partnership with the present. Two radically different answers to the question: where do materials come from?"
      },
      {
        "id": 627,
        "type": "method",
        "reason": "Formafantasma's Cambio (2020) maps the timber industry's material flows — design research through institutional investigation. Oxman's Silk Pavilion (2013) maps silkworm behaviour through environmental variables — design research through biological experiment. Both treat the studio as a laboratory; one studies systems, the other breeds them."
      },
      {
        "id": 43,
        "type": "lineage",
        "reason": "The Eameses' Powers of Ten (1977) zooms between cosmic and atomic scales to reveal that design operates at every magnitude. Oxman's Silk Pavilion (2013) operates between architectural and cellular scales simultaneously — the macro structure and the worm's micro-spinning are one process. Both insist that scale is not a boundary but a spectrum."
      }
    ],
