    "wikiTitle": "Paris_M%C3%A9tro_entrances",
    "description": "Cast-iron entrance canopies and railings for the Paris Métro designed as organic structures — stems, tendrils, and seed-pod lamp standards that grow from the pavement like metallic plants. The ironwork was cast from standardised modular components that could be assembled in different configurations for different station sizes. Guimard designed 141 entrances; 86 survive. The Abbesses station retains a complete glass-and-iron canopy.",
    "significance": "Guimard solved the problem of giving a brand-new transit system an instant identity by making the entrances unmistakable — you don't read the sign, you recognise the organism. The iron plants mark their stations the way a church spire marks a parish. That the organic forms were achieved through modular industrial casting, not handwork, is the hidden radicalism: Art Nouveau meeting mass production.",
    "connections": [
      {
        "id": 55,
        "type": "sameProblem",
        "reason": "Vignelli's New York Subway signage (1970) creates transit identity through systematic typography — Helvetica at every station, consistency as recognition. Guimard's Métro entrances (1900) create transit identity through organic sculpture — iron plants at every station, uniqueness as recognition. Two solutions to the same problem — how do you brand an underground railway? — separated by seventy years and opposite aesthetics."
      },
      {
        "id": 650,
        "type": "lineage",
        "reason": "Dresser's Claret Jug (1879) uses industrial metal casting to achieve geometric radicalism. Guimard's Métro entrances (1900) use industrial metal casting to achieve organic radicalism. Twenty years apart, both prove that the foundry can produce forms as adventurous as anything made by hand — Dresser through geometry, Guimard through botany."
      },
      {
        "id": 192,
        "type": "argument",
        "reason": "Crompton's Sampler (1930s) uses thread to create organic, natural imagery — craft as personal botanical study. Guimard's Métro entrances (1900) use cast iron to create organic, natural imagery — industry as public botanical spectacle. Two expressions of the same impulse — nature as design vocabulary — at opposite scales and in opposite materials."
      }
    ],
