    "collection": "Stedelijk Museum, Amsterdam",
    "movement": "Dutch Critical Design",
    "wikiTitle": null,
    "description": "A wall calendar for the Dutch Post Office that uses found photographs — news images, advertising fragments, amateur snapshots — collaged and overprinted with calendar dates in deliberately irregular typography. The months do not look 'designed' in the Crouwel sense; they look argued, contested, political. Van Toorn treated every commission as an opportunity for visual journalism — the calendar is not decoration but commentary.",
    "significance": "Van Toorn's famous debate with Wim Crouwel (1972) staged the fundamental argument in Dutch graphic design: should the designer be a neutral transmitter of information (Crouwel) or a critical interpreter (van Toorn)? The PTT Calendar is van Toorn's answer in practice — the designer as author, the commission as editorial platform. Every typographic choice is a political position.",
    "connections": [
      {
        "id": 660,
        "type": "argument",
        "reason": "Crouwel's New Alphabet (1967) reduces typography to a systematic grid — the designer as engineer, neutrality as method. Van Toorn's PTT Calendar (1973) explodes typography into collaged commentary — the designer as journalist, subjectivity as method. The great Dutch argument: system versus statement, made visible in two objects by the two designers who debated it publicly."
      },
      {
        "id": 167,
        "type": "zeitgeist",
        "reason": "Du Pasquier's Floating Smithereens Carpet (1983) and van Toorn's PTT Calendar (1973) both use collage logic — fragments assembled into a surface where nothing quite resolves. Du Pasquier collages pattern for visual pleasure; van Toorn collages images for political friction. Memphis ornament versus Dutch critique."
      },
      {
        "id": 448,
        "type": "method",
        "reason": "Garland's Aldermaston march poster (1962) uses graphic design as direct political action — typography on the street. Van Toorn's PTT Calendar (1973) uses graphic design as embedded political commentary — photomontage in every home. Both treat the designer as activist, but Garland protests in public while van Toorn subverts from inside the institution."
      }
    ],
