    "title": "Good Grips Peeler",
    "designer": "Smart Design (Sam Farber)",
    "year": 1990,
    "discipline": "Product",
    "origin": "United States",
    "manufacturer": "OXO International",
    "collection": "Cooper Hewitt, Smithsonian Design Museum",
    "movement": "Inclusive Design",
    "wikiTitle": "OXO_(kitchen_utensils)",
    "description": "A Y-shaped vegetable peeler with a fat, oval, black rubber handle featuring flexible fins that grip the palm without requiring tight grasp. Sam Farber watched his wife Betsey, who had arthritis, struggle with a conventional metal peeler and commissioned Smart Design to create a kitchen tool that anyone could use. The Santoprene rubber handle moulds to varying hand sizes and grip strengths. The blade is sharp stainless steel with a built-in potato eye remover.",
    "significance": "The Good Grips peeler proved that designing for disability produces better products for everyone. Farber didn't market it as an assistive device — he sold it as a premium kitchen tool. The line launched with fifteen products and built OXO into a $300 million brand. It's the founding case study of inclusive design: the moment the profession understood that constraints are generative, not limiting.",
    "connections": [
      {
        "id": 10,
        "type": "method",
        "reason": "Zanuso and Sapper's Grillo (1965) redesigns the telephone by watching how people actually hold handsets — behaviour observation as design method. Farber's Good Grips (1990) redesigns the peeler by watching his wife struggle with arthritis — disability observation as design method. Both start with the hand and work outward."
      },
      {
        "id": 37,
        "type": "sameProblem",
        "reason": "Bernadotte & Bjørn's Margrethe Bowl (1950) makes mixing easier through a rubber ring and angled interior — Scandinavian ergonomics for the kitchen. Farber's Good Grips (1990) makes peeling easier through a rubber handle and flexible fins — American ergonomics for the kitchen. Forty years between two solutions to the same question: how should a kitchen tool fit a human hand?"
      },
      {
        "id": 4,
        "type": "lineage",
        "reason": "The Castiglionis watch how people stand at telephone tables and design the Sella (1957). Farber watches his wife peel vegetables and designs the Good Grips (1990). Observation of specific, embodied behaviour producing objects that serve that behaviour exactly. The method is identical; the scale of commercial impact is not."
      }
    ],
