    "movement": "Collectible Design",
    "wikiTitle": null,
    "description": "A series of cabinets, tables, and chairs in cast bronze and gold leaf, covered in relief imagery of weapons, skulls, explosions, and industrial smokestacks. Each piece is handmade by master craftsmen using traditional lost-wax bronze casting — the same technique used for Renaissance sculpture. The surfaces are encyclopaedias of destruction rendered in precious materials. Robber Baron premiered at Design Miami in 2006, one year before the global financial crash.",
    "significance": "Studio Job detonated the boundary between furniture, sculpture, and commentary. Robber Baron treats the history of industrial capitalism as decorative programme — smokestacks and skulls cast in gold, excess critiquing excess. It launched the 'collectible design' market that would dominate design fairs for the next decade, and proved that furniture could carry political content without being didactic.",
