        "id": 601,
        "type": "method",
        "reason": "Chalayan's Afterwords (2000) transforms furniture into wearable garments on the runway — domestic objects becoming fashion. Jones and Boafo (2021) transform oil paintings into wearable jacquards on the runway — fine art becoming fashion. Both dissolve the boundary between fashion and other creative disciplines through live performance."
