    "wikiTitle": "Serpentine_Gallery_Pavilion",
    "description": "A temporary pavilion in Kensington Gardens built as a tree-like canopy of indigo-blue timber members radiating from a central trunk, with a detached roof that allows rainwater to cascade through a central oculus into a planted funnel beneath. The structure evokes the gathering tree of West African villages — the place where communities assemble for discussion. Kéré was the first architect from Africa to design the annual Serpentine Pavilion.",
    "significance": "Kéré — the first African architect to win the Pritzker Prize (2022) — demonstrated that architectural knowledge flows in both directions. The pavilion brings West African spatial principles (the communal tree, the open enclosure, the rain as celebratory element) into the heart of the Western architectural establishment. It argues that the most progressive architecture might emerge from the world's least industrialised building traditions.",
