        "type": "zeitgeist",
        "reason": "Ineke Hans's Black Gold (2004) and Adjaye's Dirty House (2002) both use blackness — of surface, of paint, of material — as a design strategy that achieves visual power through chromatic absence. Both argue that the colour black is not negative space but positive statement."
