    "collection": "n/a (building in use, Kanazawa, Ishikawa Prefecture)",
    "movement": "New Japanese Architecture",
    "wikiTitle": "21st_Century_Museum_of_Contemporary_Art,_Kanazawa",
    "description": "A circular museum with no front or back, no main entrance, no hierarchy of spaces. The building is a perfect circle in plan, 112.5 metres in diameter, containing rectangular gallery boxes of different heights arranged like furniture within the disc. Curved glass walls form the perimeter — you can see through the building from any angle. Four entrances at the cardinal points ensure no single approach dominates. The corridors between galleries are public streets.",
    "significance": "SANAA proved that a museum can be radically open without being chaotic. The circle has no preferred direction — every entrance is equal, every gallery is accessible without sequence. It anticipates how people actually move through museums: non-linearly, following curiosity rather than prescribed routes. The building's transparency means the city is always visible from inside and the art is always visible from outside.",
    "connections": [
      {
        "id": 659,
        "type": "argument",
        "reason": "Chareau's Maison de Verre (1932) uses glass blocks to achieve translucency — you see light but not through. SANAA's 21st Century Museum (2004) uses curved clear glass to achieve full transparency — you see everything from everywhere. Two glass buildings with opposite social contracts: Chareau offers privacy through diffusion, SANAA offers democracy through clarity."
      },
      {
        "id": 689,
        "type": "lineage",
        "reason": "Chipperfield's Neues Museum (2009) builds a museum by restoring and completing what already exists — architecture as continuation. SANAA's 21st Century Museum (2004) builds a museum by erasing hierarchy and sequence — architecture as liberation. Two approaches to the museum: one respects what was there, the other refuses to privilege any direction."
      },
      {
        "id": 639,
        "type": "method",
        "reason": "Bo Bardi's Bowl Chair (1951) creates a seat with no fixed front — the sitter decides their orientation. SANAA's 21st Century Museum (2004) creates a building with no fixed front — the visitor decides their entrance. Both use the circle to dissolve prescribed orientation: furniture scale and architectural scale, same principle of freedom."
      }
    ],
