    "movement": "Dutch Conceptual Design",
    "wikiTitle": null,
    "description": "A wardrobe assembled from mismatched offcuts and waste wood — each panel a different species, grain, colour, and thickness, screwed together with visible fixings into a deliberately rough-hewn cabinet. Eek made it as his graduation project from the Design Academy Eindhoven. No wood is purchased new; every piece is salvaged. The construction is intentionally crude — joints are exposed, surfaces are unfinished, proportions are approximate rather than precise.",
    "significance": "Eek's Scrapwood Cupboard inverted the value system of Dutch design. Where Droog made poverty look clever and Wanders made craft look high-tech, Eek made waste look expensive. The cupboard now sells for thousands of euros — the same material that was literally worthless becomes precious through the act of arrangement. It launched a thirty-year practice based on the proposition that discarded materials are more interesting than new ones.",
    "connections": [
      {
        "id": 600,
        "type": "method",
        "reason": "The Campanas' Favela Chair (1991) assembles furniture from scavenged wood — poverty as material source, Brazil as context. Eek's Scrapwood Cupboard (1990) assembles furniture from scavenged wood — waste as material source, Netherlands as context. Both build from salvage, but the Campanas reference social conditions while Eek references material value."
      },
      {
        "id": 673,
        "type": "zeitgeist",
        "reason": "Freitag's Messenger Bag (1993) and Eek's Scrapwood Cupboard (1990) both launch entire practices from the proposition that waste is a design material. Freitag cuts bags from truck tarpaulins; Eek builds furniture from wood offcuts. Both prove that uniqueness — each piece is different because each source is different — is a commercial advantage, not a manufacturing problem."
      },
      {
        "id": 58,
        "type": "argument",
        "reason": "Nakashima's Conoid Bench celebrates the wood's natural beauty — the material is precious and the craft is reverent. Eek's Scrapwood Cupboard celebrates the wood's previous damage — the material is discarded and the craft is deliberately rough. Two woodworkers: one honours the tree, the other honours the waste."
      }
    ],
