    "id": 696,
    "title": "Bone Chair",
    "designer": "Joris Laarman",
    "year": 2006,
    "discipline": "Furniture",
    "origin": "Netherlands",
    "manufacturer": "Joris Laarman Lab (produced by Droog)",
    "collection": "MoMA, New York",
    "movement": "Computational Craft",
    "wikiTitle": null,
    "description": "A dining chair generated by topology-optimisation software — the same algorithm used by Opel to reduce car-body weight — applied to the structure of a chair. The software adds material where stress concentrates and removes it where forces are low, producing a form that looks skeletal because it is: the chair's shape is a stress diagram of sitting, made physical in marble-resin composite. Where a conventional chair is over-engineered (uniform thickness everywhere), the Bone Chair puts material only where the body demands it.",
    "significance": "Laarman was the first designer to take computational topology optimisation — a tool from automotive and aerospace engineering — and apply it to furniture. The Bone Chair is not shaped by the designer's hand or eye; it's shaped by the algorithm's understanding of how forces flow through a seated body. It opened the field of computationally generated furniture and made MoMA's permanent collection in 2007.",
    "connections": [
      {
        "id": 638,
        "type": "lineage",
        "reason": "Prouvé's Standard Chair (1934) makes rear legs thicker than front legs because the stress diagram demands it — engineering logic visible in asymmetry. Laarman's Bone Chair (2006) makes every surface vary in thickness because the algorithm demands it — engineering logic visible in topology. Seventy years between two chairs that let structural forces determine their form."
      },
      {
        "id": 695,
        "type": "method",
        "reason": "Lovegrove's Go Chair (2001) uses finite element analysis to thin a magnesium shell to its minimum — digital optimisation at industrial scale. Laarman's Bone Chair (2006) uses topology optimisation to grow a resin composite to its minimum — digital optimisation at studio scale. Both let the computer decide where material goes; both produce forms that look organic because structural efficiency IS organic."
      },
      {
        "id": 661,
        "type": "zeitgeist",
        "reason": "Oxman's Silk Pavilion (2013) and Laarman's Bone Chair (2006) both use algorithms to determine where material goes — one lets silkworms fill a computationally defined scaffold, the other lets software carve a computationally defined skeleton. Both prove that the most materially efficient structures emerge from computation, not intuition."
      }
    ],
    "keywords": [
      "topology optimisation",
      "algorithm",
      "MoMA",
      "stress diagram",
      "marble resin",
      "Droog",
      "computational"
    ],
