    "movement": "Post-Industrial Design",
    "wikiTitle": null,
    "description": "A polypropylene chair made from a single injection-moulded piece, designed to look handmade. The surface carries deliberate imperfections — drips, sags, and rough edges that mimic wax casting rather than precision moulding. The chair costs under €100 and is fully recyclable. Seymour designed it by hand-modelling the original in wax over a steel armature, then scanning the wax model — transferring handmade irregularity into industrial production.",
    "significance": "Seymour asked: what if an injection-moulded chair looked like it was made by hand in a garage? The Workshop Chair subverts the assumption that industrial production means industrial aesthetics. The drips and sags are as precisely engineered as any smooth surface, but they make the chair feel personal rather than anonymous. Mass production imitating handcraft — the exact reverse of the Arts and Crafts position.",
    "connections": [
      {
        "id": 30,
        "type": "argument",
        "reason": "Panton's Chair (1960/67) uses injection moulding to achieve geometric perfection — the machine eliminating all human trace. Seymour's Workshop Chair (2009) uses injection moulding to simulate handmade imperfection — the machine replicating human trace. Two plastic chairs with opposite relationships to their own production: one celebrates precision, the other fakes clumsiness."
      },
      {
        "id": 415,
        "type": "method",
        "reason": "Baas's Plastic Chair in Wood (2008) reproduces a mass-produced plastic form in handmade wood — craft imitating industry. Seymour's Workshop Chair (2009) reproduces handmade wax form in mass-produced plastic — industry imitating craft. Same material-swap logic, opposite directions."
      },
      {
        "id": 694,
        "type": "zeitgeist",
        "reason": "Eek's Scrapwood Cupboard (1990) makes waste look expensive through rough assembly — the imperfect as valuable. Seymour's Workshop Chair (2009) makes plastic look handmade through simulated drips — the industrial as personal. Both argue that imperfection is a design choice, not a manufacturing failure."
      }
    ],
