    "collection": "Design Museum, London",
    "movement": "Super Normal",
    "wikiTitle": null,
    "description": "A system of moulded-ABS desk accessories — trays, cups, phone cradles, dividers — designed as the architectural equivalent of skirting boards and door handles for the desk surface. Each piece has a precise radius and wall thickness calculated to hold specific objects: a phone at 76 degrees, pens vertical, paper clips corralled. The colour is warm concrete grey. The forms are so quiet they barely register as designed objects — which is exactly the point.",
    "significance": "Hecht and Colin argue that the most important design is the design you don't notice. Formwork solves the problem of desk chaos not through organisational systems but through micro-architecture — each accessory is a tiny building that gives a specific object a specific home. It extends Jasper Morrison's Super Normal thesis into three dimensions: if the best design disappears into use, then the best desk accessory disappears into the desk.",
    "connections": [
      {
        "id": 346,
        "type": "lineage",
        "reason": "Morrison's Pill Stool (2006) reduces a stool to the minimum noticeable form — Super Normal as furniture. Hecht and Colin's Formwork (2014) reduces desk accessories to the minimum noticeable forms — Super Normal as micro-architecture. Morrison's student and collaborator, applying the same principle at a smaller scale."
      },
      {
        "id": 355,
        "type": "lineage",
        "reason": "Grcic's Mono Table (2002) reduces a table to its geometric essence for SCP — nothing unnecessary, nothing expressive. Hecht and Colin's Formwork (2014) reduces desk accessories to their geometric essence for Herman Miller — nothing unnecessary, nothing expressive. Both practise Super Normal at the scale of daily use, one generation apart."
      },
      {
        "id": 358,
        "type": "zeitgeist",
        "reason": "Blin's Stationery Tray and Hecht's Formwork are both desk-scale organisational systems designed in the 2010s — both applying architectural thinking to the territory of the work surface. Blin works in wood; Hecht works in ABS. Both treat the desk as a site that deserves the same design attention as a room."
      }
    ],
