    "title": "The Face Magazine",
    "designer": "Neville Brody",
    "year": 1981,
    "discipline": "Graphic",
    "origin": "United Kingdom",
    "manufacturer": "Wagadon (Nick Logan, publisher)",
    "collection": "V&A, London",
    "movement": "Post-Punk Graphics",
    "wikiTitle": "The_Face_(magazine)",
    "description": "Art direction for The Face magazine from 1981 to 1986 — 42 issues in which Brody dismantled and rebuilt typographic convention. Custom letterforms for every headline. Type used as image. Text columns that ignored the grid. Photographs bled, cropped, and rotated in ways that broke every rule Tschichold and Müller-Brockmann had laid down. Brody designed each issue as a complete visual argument, not a template to be filled. The magazine had a print run of under 100,000 but its influence was exponentially larger.",
    "significance": "Brody proved that editorial design could be as authored as the writing it contained. Each issue of The Face was a graphic design manifesto disguised as a style magazine. He gave typography emotional range — the same letters could shout, whisper, or stutter depending on how he set them. Together with Peter Saville's record sleeves and Jamie Reid's punk graphics, Brody's Face defined British visual culture in the 1980s.",
    "connections": [
      {
        "id": 436,
        "type": "zeitgeist",
        "reason": "Peter Saville's record sleeves for Factory Records and Brody's layouts for The Face — two Britons redesigning popular culture's visual language in the same decade, Saville through music, Brody through publishing. Both treat commercial design as fine art. Both make the envelope as important as the content."
      },
      {
        "id": 14,
        "type": "argument",
        "reason": "Tschichold's Penguin rules (1947) impose strict typographic discipline on a mass-market publication — the grid as servant of readability. Brody's Face (1981) destroys typographic discipline in a mass-market publication — the grid as victim of expression. Both prove that the designer of a magazine shapes how its culture thinks."
      },
      {
        "id": 66,
        "type": "argument",
        "reason": "Miedinger's Helvetica (1957) gives typography the neutral voice of modernism — the typeface that doesn't interfere. Brody's Face custom letterforms give typography the subjective voice of post-punk — the typeface that performs. Neutrality versus authorship, the central tension in late 20th-century graphic design."
      }
    ],
    "keywords": [
      "editorial design",
      "post-punk",
      "custom type",
      "The Face",
      "1980s",
      "V&A",
      "British graphics"
    ],
