    "collection": "V&A, London",
    "movement": "Cross-Cultural Design",
    "wikiTitle": null,
    "description": "A daybed whose steel frame is woven with handspun jute cord by craftsmen in Ahmedabad, India — the same technique used to make the charpoy, a traditional Indian rope bed found in every village. Doshi, who grew up in Mumbai, recognised the charpoy's structural intelligence: the woven surface is naturally ergonomic, breathable, and repairable by anyone with rope. The frame is Italian; the weaving is Indian; the object is neither and both.",
    "significance": "Doshi Levien refused the two available positions for Indian design in Western markets: either exoticised craft or anonymised globalism. The Charpoy Daybed is specific — it carries the memory of the village bed in its weave — without being nostalgic. It proves that cross-cultural design can be rigorous rather than decorative, and that traditional craft knowledge (the rope-tension mathematics of the charpoy) contains engineering intelligence that industrial production doesn't replicate.",
    "connections": [
      {
        "id": 639,
        "type": "lineage",
        "reason": "Bo Bardi's Bowl Chair (1951) brings Brazilian spatial freedom to European furniture — the colonised culture redefining the coloniser's chair. Doshi's Charpoy (2007) brings Indian craft intelligence to Italian manufacturing — the colonised culture redefining the coloniser's production. Both designers carry one culture's knowledge into another's system."
      },
      {
        "id": 6,
        "type": "method",
        "reason": "Ponti's Superleggera (1957) takes a traditional fisherman's chair from Chiavari and refines it to 1.7kg — vernacular form perfected by industry. Doshi's Charpoy (2007) takes a traditional village bed from India and translates it to Moroso — vernacular technique preserved by industry. Both extract design intelligence from craft traditions rather than replacing them."
      },
      {
        "id": 475,
        "type": "zeitgeist",
        "reason": "Barber's De La Warr Pavilion Chair (2003) and Doshi's Charpoy (2007) both respond to British Modernist architecture with contemporary seating — Barber to Mendelsohn's Pavilion, Doshi to the British-Indian material exchange. Both V&A-collected, both arguing that furniture carries cultural memory."
      }
    ],
