    "collection": "MoMA, New York",
    "movement": "Personal Computing",
    "wikiTitle": "Macintosh_128K",
    "description": "The first mass-market personal computer with a graphical user interface, a mouse, and a screen integrated into the same beige plastic housing. The 9-inch monochrome display showed icons, windows, and proportional fonts rather than lines of green text. The case was designed so that the screen sat at precisely the height of a seated human's eyes. The proportions were deliberately anthropomorphic — Jobs wanted the computer to look 'friendly'. The team signed the inside of the case mould, like artists.",
    "significance": "The Macintosh proved that a computer's interface is its design — not the circuit board, not the processor, but the experience of using it. By showing that ordinary people could operate a computer through pointing and clicking rather than typing commands, it established the principle that would drive the next forty years of product design: the interface is the product. The signed case mould established Apple's culture of treating engineering as authorship.",
    "connections": [
      {
        "id": 496,
        "type": "lineage",
        "reason": "The original Macintosh (1984) integrates screen, computer, and input device into one designed object — the personal computer as unified product. Ive's iMac G3 (1998) integrates screen, computer, and aesthetic statement into one transparent shell — the personal computer as designed desire. The line from Raskin to Jobs to Ive: each generation makes the computer more beautiful, but the Macintosh establishes the principle that beauty matters."
      },
      {
        "id": 16,
        "type": "lineage",
        "reason": "Rams and Gugelot's SK 4 (1956) integrates turntable, amplifier, and radio into one restrained box — the audio system as unified designed object. Apple's Macintosh (1984) integrates screen, computer, and keyboard into one restrained box — the computer as unified designed object. Both argue that the most important design decision is not the technology but the container."
      },
      {
        "id": 758,
        "type": "lineage",
        "reason": "Apple's Macintosh (1984) creates the tool. Greiman's Does It Make Sense? (1986) creates the first major design work with it. Two years between the machine and the masterpiece — the Macintosh gave graphic design a new medium, and Greiman proved it deserved one."
      }
    ],
